export const shapeTypes=[['rectangle','Rectangle'],['ellipse','Ellipse'],['triangle','Triangle'],['diamond','Diamond'],['star','Star'],['custom','Custom']];
const safe=value=>/^#[\da-f]{6}$/i.test(value||'')?value:'#292536';
export function shapeSettings(values={}){return {shape:shapeTypes.some(([id])=>id===values.shape)?values.shape:'rectangle',color:safe(values.color),fill:/^#[\da-f]{6}$/i.test(values.fill||'')?values.fill:'#ffffff',stroke:Math.max(1,Math.min(20,Number(values.stroke)||2.5)),fillOpacity:Math.max(0,Math.min(100,Number.isFinite(Number(values.fillOpacity))?Number(values.fillOpacity):15))};}
export function customShapeObject(raw,values={}){if(raw.length<3)throw new Error('Draw a larger custom shape.');const s=shapeSettings({...values,shape:'custom'}),pad=s.stroke*2,minX=Math.min(...raw.map(p=>p.x)),minY=Math.min(...raw.map(p=>p.y)),maxX=Math.max(...raw.map(p=>p.x)),maxY=Math.max(...raw.map(p=>p.y)),w=Math.max(12,maxX-minX+pad*2),h=Math.max(12,maxY-minY+pad*2);return {type:'shape',x:minX-pad,y:minY-pad,w,h,baseW:w,baseH:h,points:raw.map(p=>({x:p.x-minX+pad,y:p.y-minY+pad})),...s};}
export function shapeObject(start,end,values={}){const s=shapeSettings(values),x=Math.min(start.x,end.x),y=Math.min(start.y,end.y),w=Math.max(24,Math.abs(end.x-start.x)),h=Math.max(24,Math.abs(end.y-start.y));return {type:'shape',x,y,w,h,baseW:w,baseH:h,...s};}
export function shapePath(object){const w=object.w,h=object.h,p=object.shape;if(p==='ellipse')return `<ellipse cx="${w/2}" cy="${h/2}" rx="${Math.max(1,w/2-object.stroke)}" ry="${Math.max(1,h/2-object.stroke)}"/>`;if(p==='triangle')return `<path d="M ${w/2} ${object.stroke} L ${w-object.stroke} ${h-object.stroke} L ${object.stroke} ${h-object.stroke} Z"/>`;if(p==='diamond')return `<path d="M ${w/2} ${object.stroke} L ${w-object.stroke} ${h/2} L ${w/2} ${h-object.stroke} L ${object.stroke} ${h/2} Z"/>`;if(p==='star'){const points=Array.from({length:10},(_,i)=>{const a=-Math.PI/2+i*Math.PI/5,r=(i%2?w*.2:w*.46),ry=(i%2?h*.2:h*.46);return `${w/2+Math.cos(a)*r},${h/2+Math.sin(a)*ry}`}).join(' ');return `<polygon points="${points}"/>`;}if(p==='custom'){const points=(object.points||[]).map(pt=>`${pt.x*w/(object.baseW||w)},${pt.y*h/(object.baseH||h)}`).join(' ');return `<polygon points="${points}"/>`;}return `<rect x="${object.stroke/2}" y="${object.stroke/2}" width="${Math.max(1,w-object.stroke)}" height="${Math.max(1,h-object.stroke)}" rx="${Math.min(12,w/8,h/8)}"/>`;}
export function shapeMarkup(object,hitWidth=0){const s=shapeSettings(object),path=shapePath({...object,...s});return `<g fill="${s.fill}" fill-opacity="${s.fillOpacity/100}" stroke="${s.color}" stroke-width="${s.stroke}" stroke-linejoin="round">${path}</g>${hitWidth?`<g class="vector-hit" fill="transparent" stroke="transparent" stroke-width="${hitWidth}">${path}</g>`:''}`;}
export function shapeControls(values,disabled=false){const s=shapeSettings(values),off=disabled?'disabled':'';return `<div class="shape-settings"><div class="draw-label">Shape</div><div class="shape-grid" role="group" aria-label="Shape type">${shapeTypes.map(([id,name])=>`<button class="shape-option ${s.shape===id?'chosen':''}" data-shape="${id}" aria-pressed="${s.shape===id}" ${off}><span class="shape-glyph shape-${id}"></span><span>${name}</span></button>`).join('')}</div><div class="property-row"><label>Outline</label><input data-shape-prop="color" type="color" value="${s.color}" ${off}></div><div class="property-row"><label>Fill</label><input data-shape-prop="fill" type="color" value="${s.fill}" ${off}></div><div class="draw-range"><label>Fill opacity</label><output id="shape-opacity-value">${s.fillOpacity}%</output><input data-shape-prop="fillOpacity" type="range" min="0" max="100" step="1" value="${s.fillOpacity}" ${off}></div><div class="draw-range"><label>Outline width</label><output id="shape-width-value">${s.stroke} px</output><input data-shape-prop="stroke" type="range" min="1" max="20" step=".5" value="${s.stroke}" ${off}></div><p class="draw-description">Choose Custom, then draw a closed silhouette. Duplicate it to reuse it anywhere.</p></div>`;}
